"""Source-derived indexes, constraints and RI trigger binding rules."""
import json,re
import package_0090_source_closure as q
import package_0090_reachable_v2 as e
from package_0090_reachable_v2_ddl import DDL,generated,name

def prepare(r):
 m=DDL(r);records=list(m.constraints);indexes=[]
 for c in records:
  s=c['source']
  if s['contype'] in ['CONSTR_PRIMARY','CONSTR_UNIQUE']:
   indexes.append(dict(relation=c['relation'],name=s['conname'],keys=[x['String']['sval'] for x in s['keys']],unique=True,primary=s['contype']=='CONSTR_PRIMARY',method='btree',predicate=None,source='SQL constraint index',nulls_not_distinct=bool(s.get('nulls_not_distinct'))))
 for item in m.indexes:
  s=item['source'];q.require(all('name'in x['IndexElem'] for x in s['indexParams']),'Expression index expansion required');indexes.append(dict(relation=item['relation'],name=s['idxname'],keys=[x['IndexElem']['name'] for x in s['indexParams']],unique=bool(s.get('unique')),primary=False,method=s['accessMethod'],predicate=s.get('whereClause'),source='Canonical CREATE INDEX',nulls_not_distinct=bool(s.get('nulls_not_distinct'))))
 indexes += [dict(relation='public.flyway_schema_history',name='flyway_schema_history_pk',keys=['installed_rank'],unique=True,primary=True,method='btree',predicate=None,source='Pinned Flyway constructor',nulls_not_distinct=False),dict(relation='public.flyway_schema_history',name='flyway_schema_history_s_idx',keys=['success'],unique=False,primary=False,method='btree',predicate=None,source='Pinned Flyway constructor',nulls_not_distinct=False)]
 # Bootstrap indexes are declared in BKI; constraint promotion is a separate
 # explicit post-bootstrap input, not inferred from observed pg_constraint.
 text=(e.OUT/'provider/postgres.bki').read_text();catalogs={'pg_authid','pg_auth_members','pg_db_role_setting'}
 for match in re.finditer(r'declare (unique )?index (\w+) \d+ on (\w+) using (\w+)\s*\(([^\n]+)\)',text):
  unique,idx,rel,method,keys=match.groups()
  if rel in catalogs:indexes.append(dict(relation='pg_catalog.'+rel,name=idx,keys=[part.strip().split()[0] for part in keys.split(',')],unique=bool(unique),primary=False,method=method,predicate=None,source='BKI declare index',nulls_not_distinct=False))
 for raw in json.loads(r.parser((e.OUT/'provider/system_constraints.sql').read_text()))['stmts']:
  a=raw['stmt'].get('AlterTableStmt')
  if not a or a['relation']['relname'] not in catalogs:continue
  table='pg_catalog.'+a['relation']['relname']
  for command in a['cmds']:
   c=command['AlterTableCmd']['def']['Constraint'];index=next(x for x in indexes if x['relation']==table and x['name']==c['indexname']);index['primary']=c['contype']=='CONSTR_PRIMARY';source=dict(contype=c['contype'],conname=c.get('conname') or c['indexname'],keys=[{'String':{'sval':key}} for key in index['keys']],deferrable=False,initdeferred=False,indexname=c['indexname']);records.append(dict(relation=table,source=source,classification='BOOTSTRAP_CURRENTNESS_INTEGRITY_METADATA'))
 records.append(dict(relation='public.flyway_schema_history',source=dict(contype='CONSTR_PRIMARY',conname='flyway_schema_history_pk',keys=[{'String':{'sval':'installed_rank'}}]),classification='FLYWAY_HISTORY_INTEGRITY'))
 nn=m.not_null+[dict(relation='public.flyway_schema_history',column=c['name'],conname=generated('flyway_schema_history',c['name'],'not_null'),attnum=c['attnum']) for c in json.loads((e.OUT/'column-v2.json').read_text())['columns'] if c['relation']=='public.flyway_schema_history' and c['not_null']]
 # parse_utilcmd.c transformIndexConstraint queues SQL NOT NULL rows
 # for every PRIMARY KEY USING INDEX column, even when BKI attnotnull was set.
 for index in indexes:
  if index['source']=='BKI declare index' and index['primary']:
   for column in index['keys']:nn.append(dict(relation=index['relation'],column=column,conname=generated(index['relation'].split('.')[-1],column,'not_null')))
 for item in nn:records.append(dict(relation=item['relation'],source=dict(contype='CONSTR_NOTNULL',conname=item['conname'],keys=[{'String':{'sval':item['column']}}]),classification='SQL_NOT_NULL_COLUMN_INTEGRITY'))
 e.save('constraint-v2.json',dict(constraints=records,total=len(records),bootstrap_not_null_rule='BKI DefineAttr sets flags directly; SQL user/history NOT NULL rows and system_constraints PRIMARY KEY USING INDEX rows are generated by parse_utilcmd transformIndexConstraint/heap factory rules',independent=True))
 e.save('index-v2.json',dict(indexes=indexes,total=len(indexes),default_opclass_rule='Exact PG18 BKI default btree opclass for each source column type; collations follow column component; default ASC NULLS LAST option bits 0; no expressions or INCLUDE attributes in this root set',independent=True))
 print('Full constraints',len(records),'indexes',len(indexes))
if __name__=='__main__':
 import sys
 from pathlib import Path
 sys.path.insert(0,str(Path.home()/'.codex/tmp/package0090-pglast-8.5'));from pglast.parser import parse_sql_json
 prepare(e.Resolver(parse_sql_json))
